-- Recompenses des missions de domaine et de fief : notre table garrssion_mission_reward etait VIDE, le core
-- donnait toujours la meme recompense par defaut (Blez, 04/10/2026). Reprise de LegionCore (« Export of
-- mission_reward.db2 ») : XP de champion, objet, monnaie, capacite bonus, credit de quete.
DROP TABLE IF EXISTS garrison_mission_reward;
CREATE TABLE garrison_mission_reward (
  MissionID int NOT NULL, RewardXP int DEFAULT 0, RewardItemID int DEFAULT 0, ItemAmount int DEFAULT 0,
  CurrencyID int DEFAULT 0, CurrencyValue int DEFAULT 0, BonusAbilityID int NOT NULL DEFAULT 0,
  KillCredit int unsigned NOT NULL DEFAULT 0, PRIMARY KEY (MissionID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
